validate_doc_update:
function (newDoc, oldDoc, userCtx) {
  if (newDoc._deleted) {
    // seul un admin peut supprimer un doc terrain
    if (userCtx.roles.indexOf('_admin') === -1) throw({forbidden: 'suppression interdite'});
    return;
  }
  if (newDoc._id.indexOf('ticket:') !== 0) throw({forbidden: 'prefixe _id invalide'});
  if (newDoc.type !== 'ticket') throw({forbidden: 'type invalide'});
  if (newDoc.schemaVersion !== 1) throw({forbidden: 'schemaVersion non supportee'});
  var req = ['clientId','ticketType','urgency','title','siteId','reporterId','createdAtField'];
  for (var i=0;i<req.length;i++) if (!newDoc[req[i]]) throw({forbidden: 'champ requis manquant: '+req[i]});
  if (['PANNE_CRITIQUE','MAINTENANCE_PREVENTIVE','DEMANDE_PIECE'].indexOf(newDoc.ticketType) === -1) throw({forbidden: 'ticketType invalide'});
  if (['N1_BLOQUANT','N2_MAJEUR','N3_MINEUR'].indexOf(newDoc.urgency) === -1) throw({forbidden: 'urgency invalide'});
  // immuabilite : clientId et reporterId ne changent jamais
  if (oldDoc) {
    if (oldDoc.clientId !== newDoc.clientId) throw({forbidden: 'clientId immuable'});
    if (oldDoc.reporterId !== newDoc.reporterId) throw({forbidden: 'reporterId immuable'});
  }
}
